What does the following pseudocode output?

def mystery(n):
    if n <= 1:
        return n
    return mystery(n-1) + mystery(n-2)

print(mystery(6))

What does the following pseudocode output?

def compute(arr):
    total = 0
    for i from 0 to len(arr)-1:
        for j from i+1 to len(arr)-1:
            total = total + 1
    return total

print(compute([5, 10, 15, 20]))

What is the output of the following Python code?

class Animal:
    sound = 'generic'
    def speak(self):
        return self.sound

class Dog(Animal):
    sound = 'woof'

d = Dog()
print(d.speak())

What is the output of the following Python code?

try:
    x = int('42abc')
except ValueError:
    x = -1
except TypeError:
    x = -2
finally:
    x += 10
print(x)

What is the output of the following Python code?

class Shape:
    def __init__(self, sides):
        self.sides = sides
    def describe(self):
        return f'Shape with {self.sides} sides'

class Triangle(Shape):
    def __init__(self):
        super().__init__(3)

t = Triangle()
print(t.describe())

What is the output of the following Java code?

import java.util.ArrayList;
public class Main {
    public static void main(String[] args) {
        ArrayList<Integer> list = new ArrayList<>();
        for (int i = 0; i < 5; i++) list.add(i * 2);
        list.remove(Integer.valueOf(4));
        System.out.println(list);
    }
}
